"""Generate or verify protocol documentation from the live contracts."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from mokioclaw.core.protocol import (
    CAPABILITIES,
    EVENTS,
    PARAMS,
    PROTOCOL_VERSION,
    EventEnvelope,
    RpcRequest,
    RpcResponse,
)


def render() -> str:
    lines = [
        "# MokioClaw Wire Protocol",
        "",
        "Generated by `scripts/gen_protocol_doc.py`; do not edit by hand.",
        "",
        f"Protocol version: {PROTOCOL_VERSION}. Transport: loopback TCP, JSON-RPC 2.0 over NDJSON.",
        "",
        "Legacy clients may omit protocol_version. status advertises capabilities: "
        + ", ".join(CAPABILITIES)
        + ".",
        "",
        "Errors: parse -32700, invalid request -32600, unknown method -32601, invalid parameters -32602.",
        "Existing business errors retain their result/error representation.",
        "",
    ]
    models = {
        "RpcRequest": RpcRequest,
        "RpcResponse": RpcResponse,
        "EventEnvelope": EventEnvelope,
        **PARAMS,
        **EVENTS,
    }
    for name, model in models.items():
        lines.extend(
            [
                f"## {name}",
                "",
                "```json",
                json.dumps(model.model_json_schema(), ensure_ascii=False, indent=2),
                "```",
                "",
            ]
        )
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = Path(__file__).resolve().parents[1] / "docs/WIRE_PROTOCOL.md"
    expected = render()
    if args.check:
        if not path.exists() or path.read_text() != expected:
            raise SystemExit(
                "Protocol documentation is stale; run uv run python scripts/gen_protocol_doc.py"
            )
    else:
        path.write_text(expected)


if __name__ == "__main__":
    main()
